local hopping = false
local function httpGetJson(url)
    local body
    local req = (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request) or http_request or request or (getgenv and getgenv().request)
    if req then local ok, res = pcall(req, { Url = url, Method = "GET" }); if ok and type(res) == "table" then body = res.Body or res.body end end
    if not body or body == "" then local ok, res = pcall(function() return game:HttpGet(url) end); if ok then body = res end end
    if not body or body == "" then return nil end
    local ok, data = pcall(function() return HttpService:JSONDecode(body) end)
    if ok then return data end
    return nil
end
local function serverHop()
    if hopping then return end
    hopping = true
    local placeId = game.PlaceId
    local list, cursor, scanned = {}, nil, 0
    for _ = 1, 10 do
        local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100"):format(placeId)
        if cursor then url = url .. "&cursor=" .. cursor end
        local data = httpGetJson(url)
        if not data or type(data.data) ~= "table" then break end
        for _, s in ipairs(data.data) do
            scanned += 1
            if type(s.playing) == "number" and s.id ~= game.JobId and s.playing < (s.maxPlayers or 999) then list[#list + 1] = s end
        end
        if data.nextPageCursor and data.nextPageCursor ~= "" then cursor = data.nextPageCursor else break end
        task.wait(0.1)
    end
    if #list == 0 then notify(scanned == 0 and "Hop: API diblokir executor" or "Hop: tak ada server"); hopping = false; return end
    table.sort(list, function(a, b) return a.playing < b.playing end)
    notify(("Hop: %d server ditemukan"):format(#list))
    local idx, conn = 0, nil
    local function tryNext()
        idx = idx + 1
        local s = list[idx]
        if not s then if conn then conn:Disconnect() end; hopping = false; notify("Hop: semua gagal"); return end
        pcall(function() TeleportService:TeleportToPlaceInstance(placeId, s.id, lp) end)
    end
    conn = TeleportService.TeleportInitFailed:Connect(function(who) if who == lp then task.wait(0.5); tryNext() end end)
    tryNext()
    task.delay(25, function() if conn then conn:Disconnect() end; hopping = false end)
end
